                Cell::Integer(i64::try_from(ordinal).map_err(|_| ValueError::new(ValueRefusalKind::WorkLimit, "Jack ordinal exceeds signed range"))?),
                Cell::Text(&value.name),
                Cell::Text(match value.kind {
