};
const SQL: &str = include_str!("🗄️.sql");
const TABLES: [(&str, usize); 32] = [
    ("process3_document", 3),
    ("process3_stock_pose", 23),
    ("process3_stock_payload", 4),
    ("process3_stock_payload_pose", 23),
