    ("process3_capability", 7),
    ("process3_recipe_disc_cut", 4),
    ("process3_recipe_blade_cut", 5),
    ("process3_recipe_pocket_cut", 4),
    ("process3_recipe_bore_drill", 4),
    ("process3_recipe_cylinder_attach", 4),
