        }
        MeasureRecipe::CylinderAttach { radius, length } => {
            put(out, 18, &[Cell::Integer(owner), Cell::Text(radius), Cell::Text(length)])?;
        }
        MeasureRecipe::BoxAttach { width, depth, height } => {
