        let mut row = Cells::new(&[Cell::Integer(doc)]);
        row.xyz(camera.position);
        row.xyz(camera.target);
        row.float(camera.zoom);
        row.insert(out, 11)?;
        out.insert(TABLES[12].0, &[Cell::Integer(doc), Cell::Text(&v.meta.description)])?;
        out.checkpoint_total(total)?;
        Ok(())
