fn invalid(message: impl Into<String>) -> ValueError { ValueError::new(ValueRefusalKind::InvalidValue, message) }

fn class(v: f64) -> &'static str {
    if v.is_nan() {
        "nan"
    } else if v == f64::INFINITY {
        "positiveInfinity"
    } else if v == f64::NEG_INFINITY {
        "negativeInfinity"
    } else {
        "finite"
    }
