fn emit(p:&mut RowWriter<'_,'_>,table:&str,key:Option<i64>,values:&[FieldCell<'_>])->Result<i64,ValueError>{let mut buffer=[Cell::Null;31];for(index,value)in values.iter().enumerate(){buffer[index]=match value{FieldCell::Borrowed(cell)=>*cell,FieldCell::Decimal(value)=>Cell::Text(value.text())};}let borrowed=&buffer[..values.len()];if let Some(key)=key{p.insert_key(table,key,borrowed)?;Ok(key)}else{p.insert(table,borrowed)}}
fn ordered<T:SqlField>(p:&mut RowWriter<'_,'_>,table:&str,parent:i64,values:&[T])->Result<(),ValueError>{for(ordinal,value)in values.iter().enumerate(){let mut c=FieldCells::new();c.push(FieldCell::Borrowed(Cell::Integer(parent)));c.push(FieldCell::Borrowed(Cell::Integer(i64::try_from(ordinal).map_err(|e|invalid(e.to_string()))?)));value.append(&mut c);emit(p,table,None,&c)?;}Ok(())}
