trait RegisterSql:Sized{
 const REGISTER:&'static str;
 fn admit_native(values:&[semio_framework_dsl_record::FieldValue],native:&mut semio_framework_value::NativeDecodeControl<'_>,count:&mut usize,maximum:usize,bytes:&mut usize,value_maximum:usize)->Result<(),ValueError>;
 fn rows(&self)->Result<usize,ValueError>;
 fn project(&self,p:&mut RowWriter<'_,'_>,ordinal:usize)->Result<(),ValueError>;
