}
fn quantity(p:&mut RowWriter<'_,'_>,entity:i64,slot:&str,table:&str,v:&QuantitySpec)->Result<(),ValueError>{let mut c=FieldCells::new();c.push(FieldCell::Borrowed(Cell::Integer(entity)));c.push(FieldCell::Borrowed(Cell::Text(slot)));fields!(c;v;unit,min,max,target,current,forecast,peak,average);let id=emit(p,"architect_quantity_spec",None,&c)?;p.insert_key(table,entity,&[Cell::Integer(id)])}
fn read_quantity(r:&mut Reader<'_,'_,'_>,entity:i64,slot:&str,table:&'static str)->Result<QuantitySpec,ValueError>{let link=r.body(table,entity,2)?;let row=r.body("architect_quantity_spec",link.integer(1)?,25)?;if row.integer(1)?!=entity||row.text(2)?!=slot{return Err(invalid("Architect quantity belongs to a different entity or slot"))}let mut i=3;let n=&mut*r.native;Ok(QuantitySpec{unit:SqlField::read(row,&mut i,n)?,min:SqlField::read(row,&mut i,n)?,max:SqlField::read(row,&mut i,n)?,target:SqlField::read(row,&mut i,n)?,current:SqlField::read(row,&mut i,n)?,forecast:SqlField::read(row,&mut i,n)?,peak:SqlField::read(row,&mut i,n)?,average:SqlField::read(row,&mut i,n)?})}
macro_rules! register_sql{
 ($type:ty,$register:literal,$table:literal;[$($scalar:ident:$scalar_type:ty),*];[$($list:ident:$list_type:ty=>$edge:literal),*];[$($quantity:ident=>$quantity_edge:literal),*])=>{
 impl RegisterSql for $type{
  const REGISTER:&'static str=$register;
  fn admit_native(values:&[semio_framework_dsl_record::FieldValue],native:&mut semio_framework_value::NativeDecodeControl<'_>,count:&mut usize,maximum:usize,bytes:&mut usize,value_maximum:usize)->Result<(),ValueError>{if values.is_empty(){return Ok(())}let spec=Self::__dsl_spec_controlled(native)?;let header_spec=EntityHeader::__dsl_spec_controlled(native)?;let ownership_spec=Ownership::__dsl_spec_controlled(native)?;native.scoped_stage(|native|{native.begin_stage(values.len())?;for value in values{native.step()?;let row=native_record(value)?;admit_header(row,&spec,&header_spec,&ownership_spec,native,count,maximum)?;native_cells::header($register,row,&spec,native,bytes,value_maximum)?;native_cells::add(bytes,8,value_maximum)?;$(native_cells::add(bytes,<$scalar_type as NativeSqlField>::size(native_field(row,&spec,stringify!($scalar))?,native)?,value_maximum)?;)*$(let values=native_list(native_field(row,&spec,stringify!($list))?)?;add_rows(count,values.len(),maximum)?;native_cells::ordered::<$list_type>(values,native,bytes,value_maximum)?;)*$(add_rows(count,2,maximum)?;native_cells::quantity(stringify!($quantity),native_field(row,&spec,stringify!($quantity))?,native,bytes,value_maximum)?;)*}native.checkpoint()})}
  fn rows(&self)->Result<usize,ValueError>{let h=&self.header;let mut count=2usize;for n in[h.tags.len(),h.notes.len(),h.ownership.consultant_ids.len(),h.ownership.participant_ids.len(),$(self.$list.len(),)*] {count=count.checked_add(n).ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::WorkLimit,"Architect register row count overflow"))?;}$(let _=&self.$quantity;count=count.checked_add(2).ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::WorkLimit,"Architect quantity row count overflow"))?;)*Ok(count)}
  fn project(&self,p:&mut RowWriter<'_,'_>,ordinal:usize)->Result<(),ValueError>{let id=header(p,$register,ordinal,&self.header)?;let mut c=FieldCells::new();$(self.$scalar.append(&mut c);)*emit(p,$table,Some(id),&c)?;$(ordered(p,$edge,id,&self.$list)?;)*$(quantity(p,id,stringify!($quantity),$quantity_edge,&self.$quantity)?;)*Ok(())}
  fn restore(r:&mut Reader<'_,'_,'_>,header_row:&SqliteRow)->Result<Self,ValueError>{let header=r.header(header_row)?;let row=r.body($table,header_row.rowid,1$(+<$scalar_type as SqlField>::WIDTH)*)?;let mut index=1;$(let $scalar=<$scalar_type as SqlField>::read(row,&mut index,r.native)?;)*$(let $list=r.list::<$list_type>($edge,header_row.rowid)?;)*$(let $quantity=read_quantity(r,header_row.rowid,stringify!($quantity),$quantity_edge)?;)*Ok(Self{header,$($scalar,)*$($list,)*$($quantity,)*})}
 }
 }}
fn register_project<T:RegisterSql>(p:&mut RowWriter<'_,'_>,values:&[T])->Result<(),ValueError>{for(index,value)in values.iter().enumerate(){value.project(p,index)?;}Ok(())}
fn add_rows(count:&mut usize,size:usize,maximum:usize)->Result<(),ValueError>{*count=count.checked_add(size).filter(|count|*count<=maximum).ok_or_else(||invalid("Architect semantic rows exceed caller limit"))?;Ok(())}
