  fn admit_native(record:&semio_framework_dsl_record::RecordValue,n:&mut semio_framework_value::NativeDecodeControl<'_>,maximum:usize,value_maximum:usize)->Result<(),ValueError>{let mut count=6usize;let mut bytes=0usize;add_rows(&mut count,0,maximum)?;let spec=crate::standards::v1::subsets::any::schema::snapshot::ProgramSnapshot::__dsl_spec_controlled(n)?;admit_core(record,&spec,n,&mut count,maximum)?;native_cells::core(record,&spec,n,&mut bytes,value_maximum)?;$(<$type>::admit_native(native_list(native_field(record,&spec,stringify!($field))?)?,n,&mut count,maximum,&mut bytes,value_maximum)?;)+n.checkpoint()}
}}
