fn class(value: f64) -> &'static str {
    if value.is_nan() {
        "nan"
    } else if value == f64::INFINITY {
        "positiveInfinity"
    } else if value == f64::NEG_INFINITY {
        "negativeInfinity"
    } else {
        "finite"
    }
}
