struct Cursor<'a, 'c, 'p> {
    row: &'a SqliteRow,
    index: usize,
    control: &'c mut SqliteSnapshotControl<'p>,
}
impl<'a, 'c, 'p> Cursor<'a, 'c, 'p> {
    fn new(row: &'a SqliteRow, index: usize, control: &'c mut SqliteSnapshotControl<'p>) -> Self {
        Self { row, index, control }
    }
