        }
        Reconstruction::new(self.control)?.scalar()?;
        Ok(value)
    }
    fn optional_float(&mut self) -> Result<Option<f64>, ValueError> {
        if self.row.values.get(self.index + 1) == Some(&SqliteValue::Null) {
