            self.absent()?;
            self.absent()?;
            Ok(None)
        } else {
            self.f64().map(Some)
        }
    }
    fn xyz(&mut self) -> Result<[f64; 3], ValueError> {
        Ok([self.f64()?, self.f64()?, self.f64()?])
    }
    fn direction(&mut self) -> Result<Option<[f64; 3]>, ValueError> {
