  DrawingLayerNode::Text(v)=>{let x=scalar(&mut p,v.x)?;let y=scalar(&mut p,v.y)?;let size=scalar(&mut p,v.size)?;p.insert_key("draw_text",id,&[Cell::Integer(x),Cell::Integer(y),Cell::Text(&v.content),Cell::Integer(size)])?;},
