struct Reader<'a,'c,'p>{rows:BTreeMap<&'static str,BTreeMap<i64,&'a SqliteRow>>,groups:BTreeMap<(&'static str,usize),BTreeMap<i64,Vec<&'a SqliteRow>>>,control:&'c mut SqliteSnapshotControl<'p>}
impl<'a,'c,'p> Reader<'a,'c,'p>{
 fn new(database:&'a SqliteDatabase,control:&'c mut SqliteSnapshotControl<'p>)->Result<Self,ValueError>{control.check_database(database,SqliteSnapshotPhase::ReconstructSnapshot)?;validate_sqlite_database_schema(database,SCHEMA,control.limits())?;let mut rows=BTreeMap::new();for(name,count)in TABLES{let mut map=BTreeMap::new();for(i,row)in database.table(name)?.rows.iter().enumerate(){if row.rowid<=0||row.values.len()!=count||row.integer(0)?!=row.rowid||map.insert(row.rowid,row).is_some(){return Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue,"Draw row identity or fields"));}if i%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,i,0)?;}}rows.insert(name,map);}Ok(Self{rows,groups:BTreeMap::new(),control})}
 fn has(&self,table:&str,id:i64)->bool{self.rows.get(table).is_some_and(|v|v.contains_key(&id))}
 fn take(&mut self,table:&str,id:i64)->Result<&'a SqliteRow,ValueError>{self.rows.get_mut(table).ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue,"unknown Draw table"))?.remove(&id).ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue,"dangling or multiply owned Draw entity"))}
 fn text(&mut self,row:&SqliteRow,index:usize)->Result<String,ValueError>{Reconstruction::new(self.control)?.text(row.text(index)?)}
 fn null(row:&SqliteRow,index:usize)->Result<bool,ValueError>{Ok(row.values.get(index).ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue,"Draw column"))?==&SqliteValue::Null)}
 fn optional_text(&mut self,row:&SqliteRow,index:usize)->Result<Option<String>,ValueError>{if Self::null(row,index)?{Ok(None)}else{self.text(row,index).map(Some)}}
 fn boolean(row:&SqliteRow,index:usize)->Result<bool,ValueError>{match row.integer(index)?{0=>Ok(false),1=>Ok(true),_=>Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue,"Draw boolean"))}}
