 fn vector<const N:usize>(&mut self,row:&SqliteRow,start:usize)->Result<[f64;N],ValueError>{let mut values=[0.0;N];for(i,value)in values.iter_mut().enumerate(){*value=self.real(row,start+i)?;}Ok(values)}
 fn list(&mut self,table:&'static str,parent:i64,index:usize,order:usize)->Result<Vec<&'a SqliteRow>,ValueError>{let key=(table,index);if !self.groups.contains_key(&key){let mut groups=BTreeMap::<i64,Vec<&SqliteRow>>::new();let source=self.rows.get(table).ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue,"unknown Draw table"))?;self.control.check_rows(source.len())?;for(i,row)in source.values().enumerate(){if !Self::null(row,index)?{groups.entry(row.integer(index)?).or_default().push(*row);}if i%256==0{self.control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,i,source.len())?;}}self.groups.insert(key,groups);}let source=self.groups.get_mut(&key).unwrap().remove(&parent).unwrap_or_default();let mut sorted=BTreeMap::new();for row in source{let order=row.integer(order)?;if order<0||sorted.insert(order,row).is_some(){return Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue,"Draw duplicate or negative order"));}}let mut values=Vec::new();for(i,(order,row))in sorted.into_iter().enumerate(){if order!=ordinal(i)?{return Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue,"Draw relationship order must be contiguous"));}self.take(table,row.rowid)?;values.push(row);if i%256==0{self.control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,i,0)?;}}Ok(values)}
 fn attributes(&mut self,id:i64,rule:&str)->Result<DrawingAttributes,ValueError>{let fill_rule=FillRule::parse(rule).map_err(|e|semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue,e))?;let fill=if self.has("draw_fill",id){let row=self.take("draw_fill",id)?;Some(match row.text(1)?{"solid"=>{let v=self.take("draw_fill_solid",id)?;FillStyle::Solid{color:self.vector(v,1)?}},"linearGradient"|"radialGradient"=>{let mut stops=Vec::new();for row in self.list("draw_gradient_stop",id,1,2)?{stops.push(GradientStop{offset:self.real(row,3)?,color:self.vector(row,4)?});}if row.text(1)?=="linearGradient"{let v=self.take("draw_fill_linear",id)?;FillStyle::LinearGradient{x1:self.real(v,1)?,y1:self.real(v,2)?,x2:self.real(v,3)?,y2:self.real(v,4)?,stops}}else{let v=self.take("draw_fill_radial",id)?;FillStyle::RadialGradient{cx:self.real(v,1)?,cy:self.real(v,2)?,r:self.real(v,3)?,stops}}},_=>return Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue,"Draw fill variant"))})}else{None};let stroke=if self.has("draw_stroke",id){let row=self.take("draw_stroke",id)?;let dash=if Self::boolean(row,8)?{let mut values=Vec::new();for row in self.list("draw_stroke_dash",id,1,2)?{values.push(self.real(row,3)?);}Some(values)}else{None};Some(StrokeStyle{color:self.vector(row,1)?,width:self.real(row,5)?,cap:StrokeCap::parse(row.text(6)?).map_err(|e|semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue,e))?,join:StrokeJoin::parse(row.text(7)?).map_err(|e|semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue,e))?,dash})}else{None};Ok(DrawingAttributes{fill_rule,fill,stroke})}
 fn base(&mut self,row:&SqliteRow)->Result<DrawingLayerBase,ValueError>{if Self::null(row,1)?==Self::null(row,2)?{return Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue,"Draw ambiguous forest owner"));}let t=self.take("draw_transform",row.rowid)?;Ok(DrawingLayerBase{id:self.text(row,5)?,name:self.text(row,6)?,visible:Self::boolean(row,7)?,locked:Self::boolean(row,8)?,opacity:self.real(row,9)?,blend_mode:self.text(row,10)?,transform:DrawingTransform{x:self.real(t,1)?,y:self.real(t,2)?,scale_x:self.real(t,3)?,scale_y:self.real(t,4)?,shear:self.real(t,5)?,rotation:self.real(t,6)?},attributes:self.attributes(row.rowid,row.text(11)?)?})}
 fn leaf(&mut self,row:&SqliteRow)->Result<DrawingLayerNode,ValueError>{let id=row.rowid;let base=self.base(row)?;Ok(match row.text(4)?{
  "shape"=>{let v=self.take("draw_shape",id)?;let shape_kind=self.text(v,1)?;let rect=if self.has("draw_rect",id){let v=self.take("draw_rect",id)?;Some(DrawingRect{x:self.real(v,1)?,y:self.real(v,2)?,width:self.real(v,3)?,height:self.real(v,4)?})}else{None};let ellipse=if self.has("draw_ellipse",id){let v=self.take("draw_ellipse",id)?;Some(DrawingEllipse{cx:self.real(v,1)?,cy:self.real(v,2)?,rx:self.real(v,3)?,ry:self.real(v,4)?})}else{None};let circle=if self.has("draw_circle",id){let v=self.take("draw_circle",id)?;Some(DrawingCircle{cx:self.real(v,1)?,cy:self.real(v,2)?,r:self.real(v,3)?})}else{None};let line=if self.has("draw_line",id){let v=self.take("draw_line",id)?;Some(DrawingLine{x1:self.real(v,1)?,y1:self.real(v,2)?,x2:self.real(v,3)?,y2:self.real(v,4)?})}else{None};let polygon=if self.has("draw_polygon",id){self.take("draw_polygon",id)?;let mut points=Vec::new();for v in self.list("draw_polygon_point",id,1,2)?{points.push(self.vector(v,3)?);}Some(DrawingPolygon{points})}else{None};DrawingLayerNode::Shape(DrawingShapeBody{base,shape_kind,rect,ellipse,circle,line,polygon})},
  "path"=>{self.take("draw_path",id)?;let mut segments=Vec::new();for row in self.list("draw_segment",id,1,2)?{let key=row.rowid;let kind=row.text(3)?;let to=if kind=="close"{[0.0;2]}else{let v=self.take("draw_segment_to",key)?;self.vector(v,1)?};segments.push(match kind{"move"=>PathSegment::Move{to},"line"=>PathSegment::Line{to},"quad"=>{let v=self.take("draw_segment_quad",key)?;PathSegment::Quad{ctrl:self.vector(v,1)?,to}},"cubic"=>{let v=self.take("draw_segment_cubic",key)?;PathSegment::Cubic{ctrl1:self.vector(v,1)?,ctrl2:self.vector(v,3)?,to}},"arc"=>{let v=self.take("draw_segment_arc",key)?;PathSegment::Arc{rx:self.real(v,1)?,ry:self.real(v,2)?,rotation:self.real(v,3)?,large_arc:Self::boolean(v,4)?,sweep:Self::boolean(v,5)?,to}},"close"=>PathSegment::Close,_=>return Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue,"Draw segment variant"))});}DrawingLayerNode::Path(DrawingPathBody{base,segments})},
  "text"=>{let v=self.take("draw_text",id)?;DrawingLayerNode::Text(DrawingTextBody{base,x:self.real(v,1)?,y:self.real(v,2)?,content:self.text(v,3)?,size:self.real(v,4)?})},
  "image"=>{let v=self.take("draw_image",id)?;DrawingLayerNode::Image(DrawingImageBody{base,image_key:self.text(v,1)?,width:self.real(v,2)?,height:self.real(v,3)?})},
  "group"=>{let v=self.take("draw_group",id)?;DrawingLayerNode::Group(DrawingGroupBody{base,isolation:Self::boolean(v,1)?,children:Vec::new()})},
  "boolean"=>{let v=self.take("draw_boolean",id)?;let operation=self.text(v,1)?;let mut children=Vec::new();for v in self.list("draw_boolean_child",id,1,2)?{children.push(self.text(v,3)?);}DrawingLayerNode::Boolean(DrawingBooleanBody{base,operation,children})},
