pub fn retire(value:DrawingSnapshot){let mut cursor=store::ArtifactOwnedValueRetirementFactory::retire_owned(&crate::schema::owned::DrawingSnapshotRetirementFactory,value);loop{match cursor.close_step(256,65536).expect("Draw owner retirement") {store::SnapshotRetirementStep::Complete=>break,store::SnapshotRetirementStep::Pending{..}=>{},store::SnapshotRetirementStep::Blocked=>panic!("Draw cold retirement was blocked with an owned value")}}assert!(cursor.terminal_is_empty());}
struct Forest(BTreeMap<i64,DrawingLayerNode>);
impl Drop for Forest{fn drop(&mut self){while let Some((_,node))=self.0.pop_last(){retire(DrawingSnapshot{schema:String::new(),id:String::new(),title:None,layers:vec![node],assets:BTreeMap::new(),artboard:None});}}}
fn reconstruct(database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->Result<DrawingSnapshot,ValueError>{
 let mut r=Reader::new(database,control)?;let document=r.take("draw_document",1)?;let mut s=DrawingSnapshot{schema:r.text(document,1)?,id:r.text(document,2)?,title:r.optional_text(document,3)?,layers:Vec::new(),assets:BTreeMap::new(),artboard:None};if r.has("draw_artboard",1){let row=r.take("draw_artboard",1)?;s.artboard=Some(DrawingArtboard{width:r.real(row,1)?,height:r.real(row,2)?});}
 for row in r.list("draw_asset",1,1,2)?{let key=r.text(row,3)?;if s.assets.last_key_value().is_some_and(|(v,_)|v>=&key){return Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue,"Draw asset keys must be strictly ordered"));}let asset=DrawingImageAsset{mime:r.text(row,4)?,data:r.text(row,5)?,width:Reader::optional_unsigned(row,6)?,height:Reader::optional_unsigned(row,7)?};s.assets.insert(key,asset);}
 enum Task<'a>{Node(&'a SqliteRow),Group(i64,Vec<i64>)}
 let roots=r.list("draw_layer",1,1,3)?;let root_ids=roots.iter().map(|v|v.rowid).collect::<Vec<_>>();let mut pending=Vec::new();for row in roots.into_iter().rev(){pending.push(Task::Node(row));}let mut forest=Forest(BTreeMap::new());
 while let Some(task)=pending.pop(){r.control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,0,0)?;match task{Task::Node(row)=>{let node=r.leaf(row)?;forest.0.insert(row.rowid,node);if row.text(4)?=="group"{let children=r.list("draw_layer",row.rowid,2,3)?;r.control.check_rows(pending.len().checked_add(children.len()).ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::OwnershipLimit,"Draw frontier overflow"))?)?;let ids=children.iter().map(|v|v.rowid).collect();pending.push(Task::Group(row.rowid,ids));for row in children.into_iter().rev(){pending.push(Task::Node(row));}}},Task::Group(id,children)=>{let mut node=forest.0.remove(&id).ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue,"Draw group owner"))?;let DrawingLayerNode::Group(ref mut group)=node else{return Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue,"Draw group discriminant"))};for child in children{group.children.push(forest.0.remove(&child).ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue,"Draw child owner"))?);}forest.0.insert(id,node);}}}
